total=0
for cid in ids_expected:
    p=os.path.join(OUT,cid+".json")
    data=json.dumps(P[cid],ensure_ascii=False,indent=1).encode("utf-8")
    with open(p,"wb") as f: f.write(data)
    total+=len(data)
cm=sum(1 for v in P.values() if v["trigger"]["changed_main"])
ru=sum(1 for v in P.values() if v["trigger"]["reserve_used"])
di=sum(1 for v in P.values() if v["trigger"]["disputed"])
print("written",len(P),"changed_main",cm,"reserve_used",ru,"disputed",di,"total_bytes",total)
# self-verify each file precisely by id (no listing/glob)
for cid in ids_expected:
    with open(os.path.join(OUT,cid+".json"),encoding="utf-8") as f: d=json.load(f)
    assert d["case_id"]==cid and set(d.keys())=={"case_id","prediction_text","basis","confidence","trigger"}
    assert d["basis"].splitlines()[0]=="liuyao"
    assert "systems_used" in d["basis"]
